 assert p.evaluate('TownData.trees.length')==44 and p.evaluate('TownArt.perches.length')>=8
 perches=p.evaluate('''()=>TownArt.perches.filter(p=>p.host!=='flat-awning').map(p=>{const h=TownArt.props.find(h=>h.id===p.host),a=h.image.getContext('2d').getImageData(0,0,h.image.width,h.image.height).data,left=h.x-h.image.width*h.scale/2,top=h.y-h.image.height*h.scale;const support=dx=>{for(let yy=-2;yy<=7;yy++)for(let xx=-2;xx<=2;xx++){const x=Math.floor((p.x+dx+xx-left)/h.scale),y=Math.floor((p.y+yy-top)/h.scale);if(x>=0&&y>=0&&x<h.image.width&&y<h.image.height&&a[(y*h.image.width+x)*4+3]>200)return true;}return false;};return {host:p.host,left:support(-6),right:support(3),clear:p.clear};})''');assert all(x['left']and x['right']and x['clear']for x in perches),perches
 # Painted probes confirm silhouettes occlude from behind and leave the street visible.
